const button=document.querySelector('#run'),result=document.querySelector('#result'),data=JSON.parse(document.querySelector('#suite-data').textContent),copy=JSON.parse(document.querySelector('#copy').textContent);function run(){const pass=data.every(row=>row.actual===row.expected);result.className='result '+(pass?'pass':'fail');result.textContent=pass?copy.pass:copy.fail}button.addEventListener('click',run);
